"""Original meme copy + decorative CSS. No external assets or financial claims."""
from html import escape
import streamlit as st

REACTIONS={
    'tight':('🫶','plot twist, not a personal failure.','The numbers need a new plan. You do not need a guilt trip.'),
    'pace':('🛸','the allowance is on a side quest.','Let’s get it home before payday. Meals stay in the main storyline.'),
    'safe':('😌','main character. sensible subplot.','A little breathing room looks good on you.'),
    'buffer':('👀','the emergency fund is typing…','“Bestie, I thought we agreed I was for emergencies.”'),
    'affordable':('✨','a little treat, with a plot.','The budget has read the group chat. This one fits if you follow the new cap.'),
    'free':('🪩','free plans? elite behaviour.','Finally, a price tag with immaculate vibes.'),
    'empty':('🫧','drop the wallet lore.','Cash, allowance date, basics. Three details. Less financial guesswork.'),
    'receipt':('📸','receipts or it didn’t happen.','No, literally. Scan it, check it, log it. The wallet gets the memo.'),
    'mission':('🎟️','weekend plans 🤝 weekday meals.','Your social life can have a budget without becoming a spreadsheet personality.'),
    'prices':('🍳','inflation entered the chat.','We brought dated price records. The kitchen group chat can do the maths.'),
    'anomaly':('🕵️','this transaction has side-quest energy.','Unusual is a reason to look again, not a reason to panic.'),
    'mystery':('🧃','the wallet lore runs deep.','Pick the suspect. Follow the receipts. No financial detective licence required.'),
}

def reaction(kind):
    if not st.session_state.get('meme_mode',True):return
    icon,title,copy=REACTIONS[kind]
    st.markdown(f'<div class="meme-note"><div class="meme-avatar">{icon}</div><div><div class="meme-label">WALLET GROUP CHAT</div><strong>{escape(title)}</strong><p>{escape(copy)}</p></div><span class="meme-spark" aria-hidden="true">✳</span></div>',unsafe_allow_html=True)

