def apply_mood(name):
    palettes={
        'Matcha':('#edd6a8','#a9b8a3','#f6efe1','#343d32'),
        'Lavender Haze':('#e6d7ff','#bcebdc','#f5f0fc','#292332'),
        'Midnight Study':('#c7d4ff','#f1cf8f','#e9edf8','#202a46'),
        'Peach Soda':('#ffd0a8','#efbbd9','#fff3e9','#392a2d')}
    lime,lilac,paper,ink=palettes[name]
    st.markdown(f'<style>:root{{--lime:{lime};--lilac:{lilac};--paper:{paper};--ink:{ink};}}.stApp{{background-color:var(--paper)!important;color:var(--ink)!important;}}.runway-hero{{background:var(--lime)!important;}}[data-testid="stSidebar"]{{background:var(--ink)!important;}}</style>',unsafe_allow_html=True)


