def hostel_desk(state,profile):
    import math
    st.markdown(f'''<section class="hostel-desk" aria-label="Your allowance on a late-night hostel desk"><div class="desk-grain"></div><div class="lamp-glow"></div><div class="desk-lamp" aria-hidden="true"><i></i><b></b><span></span></div><span class="desk-hour">YOUR LITTLE CORNER OF CAMPUS / AFTER HOURS</span><div class="desk-book book-back" aria-hidden="true">THE ART OF<br>MAKING IT<br>TO PAYDAY<span>VOL. 01 / HOSTEL EDITION</span></div><div class="desk-book book-front" aria-hidden="true"><small>FIELD NOTES</small><strong>class notes<br>&amp; other<br>unfinished things.</strong><span>BS-V · CAMPUS LIFE</span></div><div class="desk-headphones" aria-hidden="true"><i></i><b></b></div><div class="desk-cup" aria-hidden="true"><div class="steam s1"></div><div class="steam s2"></div><div class="steam s3"></div><div class="chai-surface"></div><span>one more?</span></div><div class="desk-note"><span class="desk-tape"></span><small>IN MY POCKET</small><strong>Rs. {profile['cash']:,.0f}</strong><p>Okay. We can work with this.</p><span class="note-doodle" aria-hidden="true">↗</span></div><div class="desk-receipt"><span class="receipt-pin"></span><small>THE ALLOWANCE PLAN</small><hr><p>days to payday <b>{state['days']}</b></p><p>reserved costs <b>Rs. {state['reserved']:,.0f}</b></p><p>emergency reserve <b>Rs. {profile['buffer']:,.0f}</b></p><hr><small>DAILY SPENDING CEILING</small><strong>Rs. {math.floor(max(0,state['daily_cap'])):,}<em> / day</em></strong><p class="receipt-foot">Includes meals + transport.<br>Commitments &amp; reserve protected.</p><div class="desk-barcode" aria-hidden="true"></div></div><span class="desk-footer">a little chai. a little planning. a little breathing room.</span></section>''',unsafe_allow_html=True)


